import{_ as d,C as e,o,c as r,j as t,a as p,E as s,a3 as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"坐忘论·简事","description":"坐忘论第四篇精读：知生有分、识事有当；权衡轻重而保全形神，不为外物耗损性命。","frontmatter":{"title":"坐忘论·简事","description":"坐忘论第四篇精读：知生有分、识事有当；权衡轻重而保全形神，不为外物耗损性命。","category":"guide","aliases":["坐忘论简事","简事四","坐忘论精读之五"],"source":["坐忘论","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/zuowang-lun/chapter-04.md","filePath":"daoism/daoist-classics/zuowang-lun/chapter-04.md","lastUpdated":1789714390000}'),c={name:"daoism/daoist-classics/zuowang-lun/chapter-04.md"};function g(b,a,u,m,v,x){const i=e("DaoReadingPrelude"),n=e("DaoTextReading"),l=e("DaoKeywordCards");return o(),r("div",null,[a[0]||(a[0]=t("h1",{id:"坐忘论·简事",tabindex:"-1"},[p("坐忘论·简事 "),t("a",{class:"header-anchor",href:"#坐忘论·简事","aria-label":'Permalink to "坐忘论·简事"'},"​")],-1)),s(i,{title:"知生有分，识事有当",summary:"【收心】处理心与念头的关系；【简事】进一步调整生活的外在结构。它不是把所有事清空，而是根据生命所需、能力限度与修道目标重新决定去取——哪些必要、哪些只是欲望附加、哪些属于分内、哪些已经足够。",points:[{label:"知分",text:"生命、时间与能力都有现实限度——不务分之所无。"},{label:"识当",text:"事情各有合适的承担者与处理方式——不任事之非当。"},{label:"知足",text:"有用者取其足，多余者亦须舍；非要非重者皆应绝之。"}],hint:"此篇可与《天隐子·斋戒》对读：一个节的是食，一个简的是事，同是「去其多余、取其足用」。"}),a[1]||(a[1]=t("h2",{id:"【原典层】原文",tabindex:"-1"},[p("【原典层】原文 "),t("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),a[2]||(a[2]=t("p",null,[t("strong",null,"一、人离不开事物，却不必承担万事")],-1)),s(n,{paragraphs:["夫人之生也，必尝于事物，事物称万，不独委于一人。巢林一枝，鸟见遗于丛泊。饮河满腹，兽不吝于洪波。外求诸物，内明诸己，知生之有分，不务分之所无，识事之有当，不任事之非当。任非当，则伤于智力；务过分，则弊于形神。身且不安，何能及道。"]}),a[3]||(a[3]=t("p",null,[t("strong",null,"二、取舍：知闲要、量轻重、识去取")],-1)),s(n,{paragraphs:["是以修道之人，莫若断简事物，知其闲要，较量轻重，识其去取，非要非重，皆应绝之。犹人食有酒肉，衣有罗绮，身有名位，财有金玉，此并情欲之余好，非益生之良药。众皆徇之，自致亡败。静而思之，何迷之甚。"]}),a[4]||(a[4]=t("p",null,[t("strong",null,"三、达生：不求生命所不需要之物")],-1)),s(n,{paragraphs:["庄云：达生之情者，不务生之所无以为。生之所无以为者，分外物也。蔬食弊衣，足养性命，岂待酒肉罗绮，然后生全哉？是故于生无所要用者，并须去之。于生之用有余者，亦须舍之。"]}),a[5]||(a[5]=t("p",null,[t("strong",null,"四、以性命为重，以外物为轻")],-1)),s(n,{paragraphs:["财有害气，积则伤人，虽少犹累，而况多乎？以隋珠而弹千仞之雀，人犹笑之，况背道德，忽性命，而从非要，以自促伐者乎？","夫以名位比道德，则名位假而贱，道德真而贵。能知贵贱，应须去取，不以名害身，不以位易志。"]}),a[6]||(a[6]=t("p",null,[t("strong",null,"五、初学不可冒充「处事无累」")],-1)),s(n,{paragraphs:["庄云：行名失己，非士也。西升经云：抱元守一，过度神仙，子未能守，但坐荣官。","若不简择，触事皆为，心劳智昏，修道事阙。","若处事安闲，在物无累者，自属证成之人。若实未成，而言无累者，诚自诳耳。"]}),a[7]||(a[7]=t("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),t("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(l,{items:[{term:"必尝于事物",pinyin:["bì","cháng","yú","shì","wù"],meaning:"依底本作「尝」，文字略显不畅，或涉版本异文。按上下文理解为：人要维持生命，必然要接触、取用和处理一定的事物。"},{term:"称万",pinyin:["chēng","wàn"],meaning:"称，举其数；万，极言其多。谓世间事物多至万端。"},{term:"不独委于一人",pinyin:["bù","dú","wěi","yú","yī","rén"],meaning:"委，委任、交付、归于承担。谓天下万事不可能也不应全部交给一个人。"},{term:"巢林一枝",pinyin:["cháo","lín","yī","zhī"],meaning:"化用《庄子·逍遥游》「鹪鹩巢于深林，不过一枝」。鸟栖只需一枝，喻生命真正的需要有限。"},{term:"饮河满腹",pinyin:["yǐn","hé","mǎn","fù"],meaning:"化用《庄子·逍遥游》「偃鼠饮河，不过满腹」。与「巢林一枝」并喻知足有度的尺度。"},{term:"生之有分",pinyin:["shēng","zhī","yǒu","fèn"],meaning:"分，非宿命意义上的注定，而是生命的限度、能够承担的范围、与实际条件相称的尺度。"},{term:"识事之有当",pinyin:["shí","shì","zhī","yǒu","dàng"],meaning:"当，合宜、应当，与时机、身份、责任相称。谓辨明事情各有其合适的承担者与处理方式。"},{term:"闲要",pinyin:["xián","yào"],meaning:"闲，次要、非急需、可以放下；要，必要、紧要。知其闲要，即分清轻重缓急。"},{term:"较量轻重",pinyin:["jiào","liàng","qīng","zhòng"],meaning:"衡量价值轻重。不能只看眼前收益，也要看它消耗什么——本篇章的价值序是性命道德重于名位财货。"},{term:"余好",pinyin:["yú","hào"],meaning:"超过实际需要以后、由情欲继续追加的部分。非由物品名称机械决定，而看实际用途、数量与内心动机。"},{term:"徇",pinyin:["xùn"],meaning:"曲从、追随，甚至不惜牺牲自身。众皆徇之，谓世人普遍追逐余好而自致损伤。"},{term:"达生",pinyin:["dá","shēng"],meaning:"通达生命实情。不是知道很多养生理论，而是明白什么真正养生、什么看似享受实则伤生。语本《庄子·达生》。"},{term:"弊衣",pinyin:["bì","yī"],meaning:"朴素甚至破旧的衣服。此处表达足用原则，非要求营养不足、衣不蔽体——损害健康同样违背贵生。"},{term:"隋珠弹雀",pinyin:["suí","zhū","tán","què"],meaning:"隋珠（亦作随珠、随侯之珠）为至贵之宝，用作弹丸射高空小鸟，是以至贵换至贱。喻为外物损伤性命。"},{term:"促伐",pinyin:["cù","fá"],meaning:"促，促短、加速耗损；伐，伤害、戕害。自促伐，谓自己以错误取舍用性命换取外物。"},{term:"害气",pinyin:["hài","qì"],meaning:"财物具有牵动、耗损心气的可能。非神秘性质，而指财富引出的保管、恐惧、比较、争夺等一系列心理与事务。"},{term:"行名失己",pinyin:["xíng","míng","shī","jǐ"],meaning:"行名，以成名为行动目的；失己，失去自己。语出《庄子》。以名声为中心者，会不断根据他人目光塑造自己。"},{term:"抱元守一",pinyin:["bào","yuán","shǒu","yī"],meaning:"《西升经》语。抱元，保守生命根元；守一，使心神不散、安守道一。与「但坐荣官」相对。"},{term:"触事皆为",pinyin:["chù","shì","jiē","wéi"],meaning:"遇到任何事情都去承担。看见问题便认为自己必须解决，任何意见都想回应，任何机会都怕错过。"},{term:"修道事阙",pinyin:["xiū","dào","shì","quē"],meaning:"阙，缺失。谓修道之事被耽误缺失——事情不会自然结束，因为每件事都引出下一件，修道永远停在「以后」。"},{term:"证成",pinyin:["zhèng","chéng"],meaning:"修证已经成熟。「处事安闲，在物无累」属证成境界，是长期积习成熟后的结果，非初学口号。"}]}),a[8]||(a[8]=h("",145))])}const q=d(c,[["render",g]]);export{y as __pageData,q as default};
